CREATE FUNCTION public.mt_test_guard_work_log() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s magic_ticket_test_sessions%ROWTYPE; BEGIN SELECT ss.* INTO s FROM magic_ticket_test_sessions ss JOIN magic_ticket_test_documents d ON d.session_id=ss.id WHERE d.pending_id=NEW.pending_id FOR UPDATE OF ss; IF FOUND AND (s.status<>'open' OR now()<s.starts_at OR now()>=s.ends_at OR NOT(NEW.ticket_code=ANY(s.ticket_codes))) THEN RAISE EXCEPTION 'ใบเบิกอยู่ในรอบทดสอบที่จบแล้ว หรือตั๋วไม่อยู่ในรอบ'; END IF; RETURN NEW; END $$;
CREATE TRIGGER mt_test_guard_event BEFORE INSERT ON public.magic_ticket_events FOR EACH ROW EXECUTE FUNCTION public.mt_test_guard_work_log();
REVOKE ALL ON FUNCTION public.mt_test_guard_work_log() FROM PUBLIC,anon,authenticated;